from fastapi import FastAPI, Request
from fastapi.templating import Jinja2Templates
import uvicorn

app = FastAPI()
templates = Jinja2Templates(directory="templates")

@app.get("/")
async def home(request: Request):
    return templates.TemplateResponse("index.html", {"request": request})

if __name__ == "main__":
    uvicorn.run(app, reload=True)

{% extends "base.html" %}

{% block content %}
<div class="jumbotron">
    <h1 class="display-4">Come in. Sit down. Tell us about your human.</h1>
    <p class="lead">Welcome to AgentClinic. We are here to address your AI-related complaints.</p>
</div>
{% endblock %}
